  code <- body(method)
  if (is.call(code) && identical(code[[1L]], quote(invisible))) code <- code[[2L]]
  native <- is.call(code) && identical(code[[1L]], quote(.Call)) && is.name(code[[2L]]) && startsWith(as.character(code[[2L]]), ".rs_")
  if (native) NULL else method
}
