.rosetta_guard <- function(native, fallback) {
  base::force(native); base::force(fallback)
  function(...) if (base::any(base::vapply(base::list(...), .rosetta_has_native, base::logical(1L)))) native(...) else fallback(...)
}
for (.rosetta_name in .rosetta_guarded) {
  for (.rosetta_pkg in base::c("base", "stats", "utils", "methods", "graphics", "grDevices")) {
    .rosetta_fallback <- base::get0(.rosetta_name, envir = base::asNamespace(.rosetta_pkg), inherits = FALSE)
    if (base::is.function(.rosetta_fallback)) {
      base::assign(.rosetta_name, .rosetta_guard(base::get(.rosetta_name), .rosetta_fallback))
      break
    }
  }
}
base::rm(list = base::intersect(base::c(".rosetta_name", ".rosetta_pkg", ".rosetta_fallback"), base::ls(all.names = TRUE)))
